const incoming = $input.first().json ?? {};
const body = (incoming.body && typeof incoming.body === 'object') ? incoming.body : incoming;

const rawMessage = body.message ?? body.chatInput ?? body.question ?? body.text ?? '';
const message = String(rawMessage ?? '').trim();

const explicitOrder = body.order_number ?? body.orderNumber ?? body.order ?? '';
const explicitEmail = body.customer_email ?? body.customerEmail ?? body.email ?? '';

const cleanOrder = (value) => {
  if (value === null || value === undefined) return '';
  const s = String(value).trim();
  if (!s) return '';
  const m = s.match(/\d{3,}/);
  return m ? m[0] : '';
};

const cleanEmail = (value) => {
  if (value === null || value === undefined) return '';
  const s = String(value).trim().toLowerCase();
  const m = s.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return m ? m[0] : '';
};

let order_number = cleanOrder(explicitOrder);
let customer_email = cleanEmail(explicitEmail);

if (!order_number && message) {
  const orderMatch = message.match(/\border(?:\s*(?:number|no\.?|#))?\s*[:#-]?\s*(\d{3,})\b/i) || message.match(/#(\d{3,})\b/);
  if (orderMatch) order_number = orderMatch[1];
}

if (!customer_email && message) customer_email = cleanEmail(message);

const orderPhrase = /\b(my\s+(?:order|package|parcel|shipment)|where\s+(?:is|are)\s+my|track(?:ing)?\s+(?:my\s+)?(?:order|package|parcel|shipment)|order\s+status|delivery\s+status|checkout\s+email|order\s+(?:number|no\.?)|has\s+my\s+.*\s+shipped|when\s+will\s+my\s+.*\s+arrive|check\s+(?:my\s+)?order)\b/i;

const looksLikeOrderRequest = Boolean(order_number) || Boolean(customer_email) || orderPhrase.test(message);
const greetingOnly = /^(hi|hello|hey|salam|assalam(?:u)?\s*alaikum|good\s+(?:morning|afternoon|evening))[!. ]*$/i.test(message);

let route = 'rag';
let needs_input = [];
let response_message = '';

if (!message && !order_number && !customer_email) {
  route = 'local';
  response_message = 'Please enter a message. I can answer Nike company questions or help check a Shopify test order.';
} else if (greetingOnly) {
  route = 'local';
  response_message = 'Hello! I can answer questions about Nike or help you check a Shopify test order. What would you like to know?';
} else if (looksLikeOrderRequest) {
  if (!order_number) needs_input.push('order_number');
  if (!customer_email) needs_input.push('customer_email');

  if (needs_input.length > 0) {
    route = 'local';
    if (needs_input.length === 2) response_message = 'Please provide your order number and the checkout email in the same message. Example: #1001, testcustomer@example.com';
    else if (needs_input[0] === 'customer_email') response_message = `Please provide the checkout email together with order #${order_number}.`;
    else response_message = `Please provide the order number together with ${customer_email}.`;
  } else {
    route = 'shopify';
  }
}

return [{
  json: {
    route, message, chatInput: message, question: message, order_number, customer_email,
    session_id: String(body.session_id ?? body.sessionId ?? ''), needs_input, response_message,
    body: { message, chatInput: message, question: message, order_number, customer_email, session_id: String(body.session_id ?? body.sessionId ?? '') }
  }
}];

const data = $input.first().json ?? {};
const success = data.success === true;
const verified = data.verified === true;

if (!success || !verified) {
  return [{ json: { success: false, verified: false, type: 'order', code: data.code || data.status_code || 'ORDER_NOT_VERIFIED', message: 'We could not verify that order with the information provided. Please check the order number and checkout email and try again.' } }];
}

return [{ json: { ...data, success: true, verified: true, type: 'order' } }];

const data = $input.first().json ?? {};

const answer = data.answer ?? data.output ?? data.response ?? data.text ?? data.message ?? data.result ?? '';

return [{ json: { success: true, type: 'company', message: typeof answer === 'string' && answer.trim() ? answer : 'I could not generate a Nike company answer right now. Please try again.' } }];
